package com.interview.patterns.visitor;

public sealed interface Expression permits NumberExpr, AddExpr, MultiplyExpr {
}

record NumberExpr(double value) implements Expression {}
record AddExpr(Expression left, Expression right) implements Expression {}
record MultiplyExpr(Expression left, Expression right) implements Expression {}

package com.interview.patterns.visitor;

public class ExpressionEvaluator {
    public double evaluate(Expression expr) {
        return switch (expr) {
            case NumberExpr(double v) -> v;
            case AddExpr(Expression left, Expression right) -> evaluate(left) + evaluate(right);
            case MultiplyExpr(Expression left, Expression right) -> evaluate(left) * evaluate(right);
        };
    }
}

package com.interview.patterns.visitor;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;

public class ExpressionEvaluatorTest {
    @Test
    public void testSimpleEvaluation() {
        var evaluator = new ExpressionEvaluator();
        // (2 + 3) * 4 = 20
        var expr = new MultiplyExpr(new AddExpr(new NumberExpr(2.0), new NumberExpr(3.0)), new NumberExpr(4.0));
        assertEquals(20.0, evaluator.evaluate(expr), 0.001);
    }
}

package com.interview.patterns.strategy;

import java.util.Map;
import java.util.HashMap;
import java.util.function.Function;

public class PaymentProcessor {
    public enum PaymentType { CARD, CRYPTO, CASH }
    public record PaymentRequest(PaymentType type, double amount) {}
    public record PaymentResult(boolean success, double fee) {}

    private final Map<PaymentType, Function<PaymentRequest, PaymentResult>> strategies = new HashMap<>();

    public PaymentProcessor() {
        strategies.put(PaymentType.CARD, req -> new PaymentResult(true, req.amount() * 0.02));
        strategies.put(PaymentType.CRYPTO, req -> new PaymentResult(true, 1.50));
        strategies.put(PaymentType.CASH, req -> new PaymentResult(true, 0.0));
    }

    public PaymentResult processPayment(PaymentRequest request) {
        var strategy = strategies.get(request.type());
        if (strategy == null) throw new IllegalArgumentException("Unsupported type: " + request.type());
        return strategy.apply(request);
    }
}

package com.interview.patterns.strategy;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class PaymentProcessorTest {
    @Test
    public void testCardPaymentFee() {
        var processor = new PaymentProcessor();
        var res = processor.processPayment(new PaymentProcessor.PaymentRequest(PaymentProcessor.PaymentType.CARD, 100.0));
        assertTrue(res.success());
        assertEquals(2.0, res.fee(), 0.001);
    }
}

package com.interview.patterns.singleton;

public class AppConfig {
    private final double taxRate;

