package com.interview.patterns.state;

public interface OrderState {
    void pay(OrderContext context);
    void ship(OrderContext context);
    void cancel(OrderContext context);
    String getStatusName();
}

package com.interview.patterns.state;

public class PendingState implements OrderState {
    public void pay(OrderContext context) {
        context.setState(new PaidState());
    }
    public void ship(OrderContext context) {
        throw new IllegalStateException("Cannot ship unpaid order");
    }
    public void cancel(OrderContext context) {
        context.setState(new CancelledState());
    }
    public String getStatusName() { return "PENDING"; }
}

package com.interview.patterns.state;

public class PaidState implements OrderState {
    public void pay(OrderContext context) {
        throw new IllegalStateException("Order already paid");
    }
    public void ship(OrderContext context) {
        context.setState(new ShippedState());
    }
    public void cancel(OrderContext context) {
        throw new IllegalStateException("Cannot cancel paid order directly");
    }
    public String getStatusName() { return "PAID"; }
}

package com.interview.patterns.state;

public class ShippedState implements OrderState {
    public void pay(OrderContext context) { throw new IllegalStateException(); }
    public void ship(OrderContext context) { throw new IllegalStateException(); }
    public void cancel(OrderContext context) { throw new IllegalStateException(); }
    public String getStatusName() { return "SHIPPED"; }
}

package com.interview.patterns.state;

public class CancelledState implements OrderState {
    public void pay(OrderContext context) { throw new IllegalStateException(); }
    public void ship(OrderContext context) { throw new IllegalStateException(); }
    public void cancel(OrderContext context) { throw new IllegalStateException(); }
    public String getStatusName() { return "CANCELLED"; }
}

package com.interview.patterns.state;

public class OrderContext {
    private OrderState state = new PendingState();

    public void setState(OrderState state) {
        this.state = state;
    }

    public OrderState getState() {
        return state;
    }

    public void pay() { state.pay(this); }
    public void ship() { state.ship(this); }
    public void cancel() { state.cancel(this); }
    public String getStatus() { return state.getStatusName(); }
}

package com.interview.patterns.state;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

public class OrderStateTest {
    @Test
    public void testLifecycle() {
        var order = new OrderContext();
        assertEquals("PENDING", order.getStatus());
        order.pay();
        assertEquals("PAID", order.getStatus());
        order.ship();
        assertEquals("SHIPPED", order.getStatus());
    }
}

package com.interview.patterns.adapter;

public interface NotificationPort {
    boolean send(String recipient, String message);
}

package com.interview.patterns.adapter;

public class TelegramNotificationAdapter implements NotificationPort {
    public boolean send(String recipient, String message) {
        // Encapsulate vendor protocol
        return recipient != null && !recipient.isBlank() && message != null;
    }
}

package com.interview.patterns.adapter;

public class AlertService {
    private final NotificationPort notificationPort;

    public AlertService(NotificationPort notificationPort) {
        this.notificationPort = notificationPort;
    }

    public boolean triggerAlert(String target, String msg) {
        return notificationPort.send(target, msg);
    }
}

package com.interview.patterns.adapter;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertTrue;

public class AlertServiceTest {
    @Test
    public void testAlertWithAdapter() {
        var adapter = new TelegramNotificationAdapter();
        var service = new AlertService(adapter);
        assertTrue(service.triggerAlert("@admin", "Critical CPU load!"));
    }
}

