package com.interview.patterns.decorator;

public interface OrderRepository {
    String findById(String id);
}

package com.interview.patterns.decorator;

public class OrderRepositoryImpl implements OrderRepository {
    public String findById(String id) {
        return "Order:" + id;
    }
}

package com.interview.patterns.decorator;

public class TimedOrderRepository implements OrderRepository {
    private final OrderRepository delegate;

    public TimedOrderRepository(OrderRepository delegate) {
        this.delegate = delegate;
    }

    public String findById(String id) {
        long start = System.nanoTime();
        try {
            return delegate.findById(id);
        } finally {
            long duration = System.nanoTime() - start;
        }
    }
}

package com.interview.patterns.decorator;

import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.assertEquals;

public class TimedOrderRepositoryTest {
    @Test
    public void testDecoratorWrapping() {
        OrderRepository repo = new TimedOrderRepository(new OrderRepositoryImpl());
        assertEquals("Order:42", repo.findById("42"));
    }
}
